// C++11-style implementation of make_unique (as shown by Meyers)
#if __cplusplus < 201402L
namespace std {
    template<typename T, typename... Ts>
    std::unique_ptr<T> make_unique(Ts&&... params) {
        return std::unique_ptr<T>(new T(std::forward<Ts>(params)...));
    }
}
#endif

class Gadget {
public:
    Gadget(int id, const std::string& name) : id_(id), name_(name) {}
private:
    int id_;
    std::string name_;
};

// Verbose, C++98 style with explicit new
std::unique_ptr<Gadget> p1(new Gadget(101, "G-1"));

// Preferred modern C++ style using make_unique
auto p2 = std::make_unique<Gadget>(202, "G-2");

// Use case where make_unique cannot be used: custom deleters
auto logDeleter = [](Gadget* g) {
    std::cout << "Deleting Gadget...\n";
    delete g;
};
std::unique_ptr<Gadget, decltype(logDeleter)> p3(
    new Gadget(303, "G-3"), 
    logDeleter
);
